const list = (value: string): string[] => value.split(';').map((item) => item.trim()).filter(Boolean)
const normalizedType = (sourceType: string): ExerciseTypes => {
  const value = sourceType.toLowerCase()
  if (/stretch|flexibility|mobility|range of motion|release/.test(value)) return ['Stretch']
  if (/strength|strengthening|resistance|endurance|motor-control|functional|balance|postural|aerobic/.test(value)) return ['Strength']
  throw new Error(`Unmapped exercise source type: ${sourceType}`)
}
const steps = (value: string): string[] => value.split(/\s*\(\d+\)\s*/).map((item) => item.trim()).filter(Boolean)
const commonErrors = (value: string): ExerciseCommonError[] => value.split(';')
  .map((pair) => {
    const [error, correction] = pair.split(' - ').map((item) => item.trim())
    return { error: error ?? '', correction: correction ?? '' }
  })
  .filter((pair) => pair.error.length > 0 && pair.correction.length > 0)

export const exerciseCatalogueExercises: Exercise[] = importedDefinitions.map((definition) => {
  const exerciseTypes = list(definition.sourceType)
  const applicationType = normalizedType(definition.sourceType)[0]
  const exerciseSteps = steps(definition.stepsText)
  return {
    id: definition.id,
    name: definition.name,
    group: definition.group ?? EXERCISE_CATALOGUE_GROUP,
    type: applicationType,
    types: exerciseTypes,
    category: definition.sourceType,
    muscles: list(definition.muscles),
    purpose: definition.purpose,
    description: definition.purpose,
    specificMuscles: list(definition.specificMuscles),
    equipmentAndEnvironment: definition.equipmentAndEnvironment,
    startingPosition: definition.startingPosition,
    steps: exerciseSteps,
    instructions: [...exerciseSteps],
    rangeAndDirection: definition.rangeAndDirection,
    breathing: definition.breathing,
    beginnerDoseAndRest: definition.beginnerDoseAndRest,
    expectedSensation: definition.expectedSensation,
    regression: definition.regression,
    progression: definition.progression,
    commonErrors: commonErrors(definition.commonErrorsText),
    tags: [definition.sourceType],
    isFavorite: false,
    duration: '',
  }
})

export const importedExercises = exerciseCatalogueExercises
